     1→import { Suspense } from 'react';
     2→import { NextIntlClientProvider } from 'next-intl';
     3→import { getMessages } from 'next-intl/server';
     4→import { notFound } from 'next/navigation';
     5→import { locales, type Locale } from '@/lib/i18n';
     6→import { Header } from '@/components/ui/Header';
     7→import { Footer } from '@/components/layout/Footer';
     8→import { AnalyticsProvider } from '@/components/providers/AnalyticsProvider';
     9→
    10→export function generateStaticParams() {
    11→  return locales.map((locale) => ({ locale }));
    12→}
    13→
    14→export default async function LocaleLayout({
    15→  children,
    16→  params: { locale },
    17→}: {
    18→  children: React.ReactNode;
    19→  params: { locale: string };
    20→}) {
    21→  // Validate locale
    22→  if (!locales.includes(locale as any)) {
    23→    notFound();
    24→  }
    25→
    26→  const messages = await getMessages();
    27→
    28→  return (
    29→    <NextIntlClientProvider messages={messages}>
    30→      <Suspense fallback={null}>
    31→        <AnalyticsProvider>
    32→          {/* Skip link for accessibility (WCAG 2.4.1) */}
    33→          <a href="#main-content" className="skip-to-main">
    34→            Skip to main content
    35→          </a>
    36→          <Header locale={locale} />
    37→          <main id="main-content">{children}</main>
    38→          <Footer locale={locale} />
    39→        </AnalyticsProvider>
    40→      </Suspense>
    41→    </NextIntlClientProvider>
    42→  );
    43→}
